pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testRegression_property() public {
        c.init(address(0x1), address(0x2), address(0x3));

        vm.prank(address(0x100));
        c.newAddressProposal(address(0x123), "DAO");

        vm.prank(address(0x101));
        c.newAddressProposal(address(0x456), "DAO");

        assertTrue(c.mapPID_address(1) == address(0x123));
    }
}
